    while (n > 0) {
        rem[i++] = n % base;  // Take remainder
        n /= base;            // Divide number by base
    }

    printf("Result: ");
    // Print digits in reverse order (since remainders come backwards)
    for (i = i - 1; i >= 0; i--)
        printf("%X", rem[i]);   // %X prints 10–15 as A–F (for base 16)
    printf("\n");
}

// Function to convert any base (2–16) number to decimal
int baseToDec(char num[], int base) {
    int len = strlen(num), val = 0, power = 0;

    // Traverse digits from right to left
    for (int i = len - 1; i >= 0; i--) {
        int digit;

        // Convert char to integer value (0–9 or A–F)
        if (num[i] >= '0' && num[i] <= '9')
            digit = num[i] - '0';
        else
            digit = num[i] - 'A' + 10;

        // Add contribution of each digit (digit × base^position)
        val += digit * pow(base, power++);
    }

    return val;  // Return decimal equivalent
}

