int baseToDec(char num[], int base) {
    int len = strlen(num);
    int val = 0;
    int power = 0;
    int i = len - 1;

    while (i >= 0) {
        int digit;

        if (num[i] >= '0' && num[i] <= '9')
            digit = num[i] - '0';
        else
            digit = num[i] - 'A' + 10;

        val += digit * pow(base, power);
        i--;
        power++;
    }

    return val;
}
